use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut array = input.as_array().unwrap().to_vec();
    array.sort_by(|a, b| {
        let key_a = a[0].as_i64().unwrap();
        let key_b = b[0].as_i64().unwrap();
        key_a.cmp(&key_b).then_with(|| a[1].as_i64().unwrap().cmp(&b[1].as_i64().unwrap()))
    });
    Value::Array(array)
}
